ruleToc.chapterList:
@css:
.title> b,.book_list>ul>li


@js:
list=[]
$=result
for(i in $){
if(String($[i]).match(/<b/)){
		list.push({
				text: " 📖 【"+$[i].text()+"】📖",
				volume: true
			})
	}
else{
		$[i].select("a").forEach(a=>{
				list.push({
						text: a.text(),
						href: a.attr("href")
					})
			})
	}
}
list

